{
  "decision": "needs_more_evidence",
  "objections": [
    {
      "severity": "minor",
      "problem": "The claim states 'always stretch your body after waking up' but the study only measured acute effects of warm-up exercises (10 min running) on Achilles tendon blood flow and stiffness, not stretching after waking up or general circulation.",
      "requested_action": "More evidence on stretching after waking up and its effect on circulation is needed."
    },
    {
      "severity": "minor",
      "problem": "The study does not compare static stretching as a warm-up exercise, so it cannot confirm if stretching improves circulation or reduces injury risk as claimed.",
      "requested_action": "More evidence on static stretching as a warm-up exercise is needed."
    },
    {
      "severity": "minor",
      "problem": "The study only measured acute effects (10 min running), not chronic effects of stretching after waking up.",
      "requested_action": "More evidence on chronic effects of stretching after waking up is needed."
    }
  ],
  "remaining_gaps": [
    "No evidence on stretching after waking up",
    "No comparison of static stretching as a warm-up exercise",
    "No chronic effects data"
  ]
}
